import{_ as i,C as n,o,c as s,j as t,a as r,G as d,a3 as l}from"./chunks/framework.exbasbhr.js";const k=JSON.parse('{"title":"PowerPoint Guide","description":"The three integration paths, add-in setup, and how ink behaves during a slide show","frontmatter":{"title":"PowerPoint Guide","description":"The three integration paths, add-in setup, and how ink behaves during a slide show"},"headers":[],"relativePath":"en/guide/ppt-guide.md","filePath":"en/guide/ppt-guide.md"}'),h={name:"en/guide/ppt-guide.md"};function p(c,e,u,g,b,m){const a=n("ArticleMetadata");return o(),s("div",null,[e[0]||(e[0]=t("h1",{id:"powerpoint-guide",tabindex:"-1"},[r("PowerPoint Guide "),t("a",{class:"header-anchor",href:"#powerpoint-guide","aria-label":'Permalink to "PowerPoint Guide"'},"​")],-1)),d(a),e[1]||(e[1]=l('<p>ICC-CE lets you annotate slides while presenting and remembers the ink of each slide separately.</p><h2 id="three-integration-paths" tabindex="-1">Three integration paths <a class="header-anchor" href="#three-integration-paths" aria-label="Permalink to &quot;Three integration paths&quot;">​</a></h2><p>ICC-CE does not rely on a single mechanism to talk to PowerPoint. It tries them in order of availability:</p><table tabindex="0"><thead><tr><th>Path</th><th>How it works</th><th>When it applies</th></tr></thead><tbody><tr><td><strong>COM automation</strong></td><td>Creates the PowerPoint application object directly</td><td>The normal case — PowerPoint just needs to be running</td></tr><tr><td><strong>ROT / OLE</strong></td><td>Grabs an existing PowerPoint instance from the Running Object Table</td><td>When COM creation fails, or PowerPoint was launched by another program first</td></tr><tr><td><strong>VSTO add-in</strong></td><td>The add-in pushes slide show events to ICC-CE</td><td>When the first two are blocked by security policy, or you want more responsive slide change events</td></tr></tbody></table><p>The app picks whichever works; no manual switching is needed. If none are available, the PowerPoint-related toolbar buttons simply don&#39;t appear.</p><h2 id="installing-the-vsto-add-in" tabindex="-1">Installing the VSTO add-in <a class="header-anchor" href="#installing-the-vsto-add-in" aria-label="Permalink to &quot;Installing the VSTO add-in&quot;">​</a></h2><p>The add-in is optional but makes slide change events noticeably more responsive:</p><ol><li>Fully exit both PowerPoint and ICC-CE</li><li>In ICC-CE settings, find the PowerPoint section and enable add-in support</li><li>Restart PowerPoint and confirm the ICC add-in is enabled under File → Options → Add-ins</li></ol><div class="warning custom-block"><p class="custom-block-title">Add-in gets disabled</p><p>Office sometimes disables add-ins automatically when startup is slow. If integration stops working, go to File → Options → Add-ins → Manage: Disabled Items and re-enable the ICC add-in.</p></div><h2 id="behaviour-during-a-slide-show" tabindex="-1">Behaviour during a slide show <a class="header-anchor" href="#behaviour-during-a-slide-show" aria-label="Permalink to &quot;Behaviour during a slide show&quot;">​</a></h2><p>Once you enter presentation mode:</p><ul><li>The toolbar gains PowerPoint-specific buttons such as previous / next slide and the slide number</li><li>Ink drawn on a slide is kept in memory <strong>per slide number</strong></li><li>Changing slides hides the current slide&#39;s ink and restores the target slide&#39;s ink</li><li>On exit, the whole deck&#39;s ink can be written to disk depending on your settings</li></ul><div class="tip custom-block"><p class="custom-block-title">Slide changes and undo</p><p>Changing slides is not part of the undo stack. If you flip by accident, use the toolbar buttons to go back — the ink is restored automatically.</p></div><h2 id="where-the-ink-is-stored" tabindex="-1">Where the ink is stored <a class="header-anchor" href="#where-the-ink-is-stored" aria-label="Permalink to &quot;Where the ink is stored&quot;">​</a></h2><p>Ink produced during a slide show goes to the <code>Saves</code> folder in the data directory, in a sub-folder named after the presentation. The path can be changed via the auto-save settings; see <a href="/website/en/guide/files-and-data">Files &amp; Data Locations</a>.</p><div class="warning custom-block"><p class="custom-block-title">Renaming a presentation</p><p>Ink is associated with the presentation&#39;s name. After renaming the pptx file, previously saved ink will no longer be matched to it automatically.</p></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>No PowerPoint buttons appear during a slide show</strong> None of the three paths connected. Make sure you are using desktop PowerPoint (not UWP or the web version), and check whether antivirus software is blocking COM calls.</p><p><strong>Ink appears on the wrong slide</strong> Usually happens with several presentations open at once. Present only one, or exit and re-enter the slide show.</p><p><strong>Ink is not saved automatically</strong> Check that auto-save is enabled and that the target directory is writable — some labs make the install directory read-only.</p>',20))])}const P=i(h,[["render",p]]);export{k as __pageData,P as default};
